 if(text.startsWith('SM1:')){const v=JSON.parse(text.slice(4));if(!Array.isArray(v)||![2,6].includes(v.length))throw Error('Invalid legacy marker.');const [id,revision,lat,lon,color,name]=v;if(!/^[0-9a-f]{12}$/.test(id)||!Number.isSafeInteger(revision)||revision<1)throw Error('Invalid marker identity.');if(v.length===2)return {kind:'delete',id,revision};if(!Number.isInteger(lat)||Math.abs(lat)>8500000||!Number.isInteger(lon)||Math.abs(lon)>18000000||!Number.isInteger(color)||color<0||color>3||typeof name!=='string'||!name.trim()||enc.encode(name).length>12||/[\x00-\x1f\x7f]/.test(name))throw Error('Invalid marker.');return {kind:'marker',id,revision,lat:lat/100000,lon:lon/100000,symbol:0,name,note:''};}
